/**
 * Test-only: what a Solana Pay merchant hands the wallet (spec 043). A SOL
 * transfer from the user to the merchant, by default with a fee sponsor as
 * fee payer that has already signed and the user's slot left empty. Keys are
 * generated by the caller at run time; nothing here is a secret.
 */
import {
  appendTransactionMessageInstructions,
  compileTransaction,
  compressTransactionMessageUsingAddressLookupTables,
  createNoopSigner,
  createTransactionMessage,
  getBase64EncodedWireTransaction,
  partiallySignTransaction,
  pipe,
  setTransactionMessageFeePayer,
  setTransactionMessageLifetimeUsingBlockhash,
  setTransactionMessageLifetimeUsingDurableNonce,
  type Address,
  type Blockhash,
  type KeyPairSigner,
  type Nonce,
} from '@solana/kit';
import { getAddMemoInstruction } from '@solana-program/memo';
import { getTransferSolInstruction } from '@solana-program/system';

export const MERCHANT_BLOCKHASH = 'GHtXQBsoZHVnNFa9YevAzFr17DJjgHXk3ycTKD5xD3Zi' as Blockhash;

export interface MerchantTransactionFixture {
  version: 'legacy' | 0;
  sponsor: KeyPairSigner;
  user: Address;
  merchant: Address;
  lamports?: bigint;
  blockhash?: Blockhash;
  /** Fee payer; the sponsor unless a test says otherwise. */
  feePayer?: Address;
  /** Another party the transaction asks to sign (it signs a memo). */
  cosigner?: Address;
  /** Who signs before the wallet sees it; the sponsor alone by default. */
  signWith?: CryptoKeyPair[];
  /** A durable-nonce lifetime instead of a blockhash, the sponsor its authority. */
  nonceAccount?: Address;
  /** A memo of this many bytes, to push the transaction past the size limit. */
  memoBytes?: number;
  /** v0 only: the merchant's address read from this lookup table. */
  lookupTable?: Address;
}

/** Base64 wire transaction, shaped by the fixture's options. */
export async function sponsoredMerchantTransaction({
  version,
  sponsor,
  user,
  merchant,
  lamports = 1_000_000n,
  blockhash = MERCHANT_BLOCKHASH,
  feePayer = sponsor.address,
  cosigner,
  signWith = [sponsor.keyPair],
  nonceAccount,
  memoBytes,
  lookupTable,
}: MerchantTransactionFixture): Promise<string> {
  const instructions = [
    getTransferSolInstruction({
      source: createNoopSigner(user),
      destination: merchant,
      amount: lamports,
    }),
    ...(cosigner || memoBytes
      ? [
          getAddMemoInstruction({
            memo: 'm'.repeat(memoBytes ?? 1),
            signers: cosigner ? [createNoopSigner(cosigner)] : [],
          }),
        ]
      : []),
  ];
  const message = pipe(
    createTransactionMessage({ version }),
    (m) => setTransactionMessageFeePayer(feePayer, m),
    (m) =>
      nonceAccount
        ? setTransactionMessageLifetimeUsingDurableNonce(
            {
              nonce: blockhash as string as Nonce,
              nonceAccountAddress: nonceAccount,
              nonceAuthorityAddress: sponsor.address,
            },
            m
          )
        : setTransactionMessageLifetimeUsingBlockhash({ blockhash, lastValidBlockHeight: 100n }, m),
    (m) => appendTransactionMessageInstructions(instructions, m)
  );
  // Test-only: the kit's message types do not follow the optional steps above.
  const compiled = compileTransaction(
    (lookupTable && version === 0
      ? compressTransactionMessageUsingAddressLookupTables(message as never, {
          [lookupTable]: [merchant],
        })
      : message) as never
  );
  const signed = signWith.length ? await partiallySignTransaction(signWith, compiled) : compiled;
  return getBase64EncodedWireTransaction(signed);
}
